//! `map_split` against C's `astMapSplit` for every class that overrides it:
//! a partial selection, a full permuted one, an index out of range, an index
//! of 0 and a repeated index. The base MapSplit and the classes that call it
//! first refuse an index out of range with AST__AXIIN; the others return no
//! split. A split is compared by its outputs and its dump, byte for byte.
//!
//! `map_split_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/map_split_probe.c`.

// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "map_split_oracle/cases.rs"]
mod cases;

use cases::Outcome;

/// Cases whose split C dumps with one `IsSimp = 1` card more than the port,
/// on a component of the simplified PermMap-and-Mapping CmpMap a full
/// permuted selection returns. The card is the only difference, so these
/// compare with `IsSimp` lines set aside; why C stamps the component is not
/// established. The signature matches `ISSIMP_DISAGREEMENTS` in
/// `test_simplify_regression.rs`, where C stamps a sub-Mapping inside a merge
/// probe it abandons.
const ISSIMP_COMPONENT_EXCLUDED: &[(&str, &str)] = &[
    (
        "ratemap_full_permuted",
        "C stamps the RateMap's encapsulated ZoomMap",
    ),
    (
        "tranmap_full_permuted",
        "C stamps one of the TranMap's ZoomMaps",
    ),
];

fn without_issimp(dump: &str) -> String {
    dump.lines()
        .filter(|l| !l.contains("IsSimp = "))
        .map(|l| format!("{l}\n"))
        .collect()
}

/// The port's dump of a case's split, if it splits.
fn split_dump(name: &str, inputs: &[usize]) -> Option<String> {
    let (_, sub) = mapping(name).map_split(inputs).ok()??;
    let any = AnyObject::from_mapping(sub.as_ref()).expect("a dumpable class");
    Some(to_native_string(&any).unwrap())
}

use ast_core::error::ErrorCode;
use ast_core::frames::BasicFrameBuilder;
use ast_core::mappings::{
    CmpMap, Composition, DynMapping, MatrixMap, NormMap, PermMap, RateMap, ShiftMap, TranMap,
    UnitMap, WcsMap, WcsProjection, WinMap, ZoomMap,
};
use ast_core::{AnyObject, to_native_string};

fn inverted(mut m: DynMapping) -> DynMapping {
    m.invert();
    m
}

fn zoom(n: usize, f: f64) -> DynMapping {
    Box::new(ZoomMap::new(n, f).unwrap())
}

/// The probe's Mapping for a case, by the case name's prefix.
fn mapping(name: &str) -> DynMapping {
    let prefix = |p: &str| name.starts_with(p);
    if prefix("unitmap_") {
        Box::new(UnitMap::new(3))
    } else if prefix("zoommap_inverted_") {
        inverted(zoom(3, 2.0))
    } else if prefix("shiftmap_inverted_") {
        inverted(Box::new(ShiftMap::new(vec![1.0, 2.0, 3.0])))
    } else if prefix("winmap_inverted_") {
        inverted(Box::new(
            WinMap::from_corners(&[0.0, 0.0], &[1.0, 1.0], &[1.0, 2.0], &[3.0, 6.0]).unwrap(),
        ))
    } else if prefix("permmap_") {
        Box::new(PermMap::new(&[2, 1, 3], &[2, 1, 3], &[]).unwrap())
    } else if prefix("matrixmap_inverted_") {
        let m = ndarray::array![[2.0, 1.0], [0.0, 3.0]];
        inverted(Box::new(MatrixMap::new(m).unwrap()))
    } else if prefix("normmap_") {
        Box::new(NormMap::new(Box::new(
            BasicFrameBuilder::new(3).build().unwrap(),
        )))
    } else if prefix("ratemap_") {
        Box::new(RateMap::new(zoom(2, 2.0), 1, 1).unwrap())
    } else if prefix("tranmap_") {
        Box::new(TranMap::new(zoom(3, 2.0), zoom(3, 2.0)).unwrap())
    } else if prefix("wcsmap_") {
        Box::new(WcsMap::new(3, WcsProjection::Tan, 1, 2).unwrap())
    } else if prefix("cmpmap_parallel_") {
        Box::new(
            CmpMap::new(
                zoom(1, 2.0),
                Box::new(ShiftMap::new(vec![1.0, 2.0])),
                Composition::Parallel,
            )
            .unwrap(),
        )
    } else {
        panic!("no Rust construction for case {name}")
    }
}

#[test]
fn map_split_matches_the_c_library() {
    let mut failures = Vec::new();
    for (name, inputs, want) in cases::CASES {
        let map = mapping(name);
        let got = map.map_split(inputs);
        let ok = match (&got, want) {
            (Err(e), Outcome::Err(code)) => {
                let expected = match *code {
                    "AXIIN" => ErrorCode::Axiin,
                    "SELIN" => ErrorCode::Selin,
                    other => panic!("unexpected code {other}"),
                };
                e.code() == expected
            }
            (Ok(None), Outcome::None) => true,
            (Ok(Some((outs, sub))), Outcome::Split(want_outs, dump)) => {
                let any = AnyObject::from_mapping(sub.as_ref()).expect("a dumpable class");
                let written = to_native_string(&any).unwrap();
                let excluded = ISSIMP_COMPONENT_EXCLUDED.iter().any(|(n, _)| n == name);
                let differs = if excluded {
                    without_issimp(&written) != without_issimp(dump)
                } else {
                    written != *dump
                };
                if differs {
                    failures.push(format!("{name}: dump\n{written}C:\n{dump}"));
                }
                outs == want_outs
            }
            _ => false,
        };
        if !ok {
            let got = got.map(|s| s.map(|(outs, _)| outs));
            failures.push(format!("{name} {inputs:?}: {got:?}, C {want:?}"));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

/// Every case in `ISSIMP_COMPONENT_EXCLUDED` still differs from C's dump; one
/// that matches has to leave the list.
#[test]
fn issimp_component_exclusions_still_differ() {
    for (name, reason) in ISSIMP_COMPONENT_EXCLUDED {
        let (_, inputs, want) = cases::CASES
            .iter()
            .find(|c| c.0 == *name)
            .expect("an excluded case exists");
        let Outcome::Split(_, dump) = want else {
            panic!("{name} is not a split in C");
        };
        let written = split_dump(name, inputs).expect("the port splits it");
        assert_ne!(
            written, *dump,
            "{name} now matches C; remove it from ISSIMP_COMPONENT_EXCLUDED ({reason})"
        );
    }
}
